#!/usr/bin/env python3
"""gen_report.py -> REPORT.md : #325 Kapitsa vs MLX on the M5 Pro, every number read from the result JSONs.
Tiers per leg: COUNTS (valid.py: no flag, <=3% foreign GPU, AC proven) | CLEAN-PHASE (a phase with <=3% foreign GPU, leg void for another phase;
legs before 18:19 3 Nov have no AC proof and are left out) | VOID (not used)."""
import json,glob,os,statistics as st,sys,datetime as dt
HERE=os.path.dirname(os.path.abspath(__file__)); os.chdir(HERE)  # inputs sit next to this script
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
import valid
AC=valid.load_ac('ac.log'); CUT=dt.datetime(2026,11,3,18,19)
def legs(label,d):
    out=[]
    for f in sorted(glob.glob('%s/results/%s-2026*.json'%(d,label))):
        r=json.load(open(f)); why=valid.judge(r,AC); a=valid.ts(r['when'])
        out.append(dict(r=r,f=os.path.basename(f),counts=not why,why=why,ac=a>=CUT and not any('battery' in w for w in why),c=r.get('contention',{}).get('phases',{})))
    return out
def clean(l,ph): p=l['c'].get(ph); return bool(p) and not p.get('flagged') and p.get('mean_foreign_gpu_pct',99)<=3
def med(v): return round(st.median(v),1) if v else None
def short(lg,key):
    """decode T0.6 / T0 / 4K / 16K: (value, n legs, tier)"""
    res={}
    spec={'dec':('decode',lambda r:r['decode_summary']['median_tps']),'dec0':('decode_greedy',lambda r:r['decode_greedy_summary']['median_tps']),
          'pf4':('prefill_4000',lambda r:[p['prefill_tps'] for p in r['prefill'] if p['target']==4000][0]),'pf16':('prefill_16000',lambda r:[p['prefill_tps'] for p in r['prefill'] if p['target']==16000][0])}
    ph,get=spec[key]
    full=[get(l['r']) for l in lg if l['counts']]
    if full: return med(full),len(full),'valid'
    cl=[get(l['r']) for l in lg if l['ac'] and clean(l,ph)]
    if cl: return med(cl),len(cl),'clean phase'
    al=[get(l['r']) for l in lg if l['ac']]
    if al: return med(al),len(al),'contended'
    return None,0,''
def longpt(lg,which,key):
    ok=[l for l in lg if (l['ac'] or l['counts']) and not any('finish_reason' in f for f in l['r'].get('flags',[]))]
    vals=[];dec_ok=[]
    for l in ok:
        s=l['r']['sweep']; pts={p['target']:p for p in s['points']}
        t=32000 if which==32 else 124220
        if t in pts and pts[t].get(key) is not None:
            if key=='decode_tps' and not clean(l,'decode'): continue
            vals.append(pts[t][key])
    tier='valid' if any(l['counts'] for l in ok) and vals else ('clean decode phase' if key=='decode_tps' else 'contended')
    return med(vals),len(vals),tier
def fmt(v): return '–' if v[0] is None else ('%s'%v[0]+('' if v[2]=='valid' else '*') if v[2]!='contended' else '(%s)'%v[0])
def ratio(a,b): return None if not a[0] or not b[0] else a[0]/b[0]
def faster(x): return 'about the same' if x is None or abs(x-1)<0.05 else ('%d%% faster (%.1fx)'%(round((x-1)*100),x) if x>1 else '%d%% slower'%round((1-x)*100))
M=[('Qwen3.8 27B','q38-27b',['kapitsa','mlxlm','mlxvlm-mtp'],'27b'),('Qwen3.6 35B-A3B','q36-35b',['kapitsa','mlxlm','mlxvlm-dflash2'],'35b'),('Lightning 30B','lightning',['kapitsa','mlxlm','mlxvlm','mlxvlm-dspark'],'lightning')]
NAMES={'kapitsa':'Kapitsa','mlxlm':'mlx-lm','mlxvlm-mtp':'mlx-vlm + MTP','mlxvlm-dflash2':'mlx-vlm + DFlash2','mlxvlm':'mlx-vlm','mlxvlm-dspark':'mlx-vlm + DSpark'}
o=[]; P=o.append
P('# #325: Kapitsa against MLX on the M5 Pro 48 GB: the 3 Nov 2026 result\n')
P('Generated by `gen_report.py` from `harness-runs*/results/*.json`; no number is typed by hand. Final for 3 Nov 2026: the GPU queue is stopped. Open items are under Limits.\n')
P('Mac: MacBook Pro M5 Pro 48 GB, macOS 26.5.2. Kapitsa: main `287c0403` (includes #892 and #897). Lightning: Kapitsa runs the NVIDIA NVFP4 checkpoint, the MLX engines the mlx-community 4-bit pack. MLX: mlx-lm 0.32.2, mlx-vlm 0.7.10, mlx 0.32.4. Settings: Kapitsa defaults (`--slots 1`, drafter named), mlx-lm server with prompt cache, 4-bit packs. 3 Nov 2026.\n')
SUMSLOT=len(o)
P('## How to read the numbers\n')
P('- **valid**: the leg passed every check: AC power proven by a 30-second power log, no harness flag, foreign GPU load 3% or less.')
P('- **\\***: a clean-phase reading. The leg as a whole was contended (WebKit of the DSH app, Slack/Edge/Kapitan helpers, 5-16% foreign GPU load in some phase), but this phase read 3% or less. Median over the legs with that clean phase.')
P('- **(n)**: contended reading only (every phase of every AC leg was above 3% foreign GPU load); shown for scale, not for a claim.')
P('- **–**: no usable reading yet. "cannot measure" means the legs voided under the rule (one retry after 10 min) because of foreign GPU load from open apps.\n')
P('## Short prompts (4K and 16K): tokens per second\n')
hl=[]
for name,pre,engs,tag in M:
    P('### %s\n'%name)
    P('| Engine | Decode T=0.6 | Decode T=0 | 4K prefill | 16K prefill | legs |'); P('|---|---|---|---|---|---|')
    R={}
    for e in engs:
        lg=legs('%s-%s'%(pre,e),'harness-runs'); R[e]={k:short(lg,k) for k in ('dec','dec0','pf4','pf16')}
        P('| %s | %s | %s | %s | %s | %d (%d valid) |'%(NAMES[e],fmt(R[e]['dec']),fmt(R[e]['dec0']),fmt(R[e]['pf4']),fmt(R[e]['pf16']),len(lg),sum(l['counts'] for l in lg)))
    k=R['kapitsa']; best=max((e for e in engs if e!='kapitsa' and R[e]['dec'][0]),key=lambda e:R[e]['dec'][0],default=None)
    P('')
    if best:
        rd=ratio(k['dec'],R[best]['dec']); rd0=ratio(k['dec0'],R[best]['dec0'])
        P('Decode: Kapitsa is **%s** than the strongest MLX path (%s); at temperature 0: %s.'%(faster(rd),NAMES[best],faster(rd0)))
        for e in engs:
            if e not in('kapitsa',best) and R[e]['dec'][0]: P('Against %s: %s.'%(NAMES[e],faster(ratio(k['dec'],R[e]['dec']))))
        hl.append((name,faster(rd),NAMES[best],'%.0f vs %.0f tok/s'%(k['dec'][0],R[best]['dec'][0])))
    else: P('No MLX decode reading yet.')
    ml=R.get('mlxlm')
    if ml and k['pf4'][0] and ml['pf4'][0]: P('4K prefill: Kapitsa is %s than mlx-lm%s.'%(faster(ratio(k['pf4'],ml['pf4'])),'' if k['pf4'][2]==ml['pf4'][2]=='valid' else ' (indicative, at least one side contended)'))
    P('')
P('## 128K prompts\n')
P('**Cannot measure on this Mac with Alish\'s apps open: foreign GPU load about 15% in the sweep phase, and swap. Rerun with apps closed.** The Kapitsa 27B 128K leg voided twice and the mlx-lm 27B leg returned no 128K token; Lightning was never reached. The appendix lists the readings that exist, from clean decode phases only.\n')
P('## Flash-Next 180B Q2_0 (the poster row)\n')
P('- The README row runs `--engine splash` with KFlash on Splash 1.5.0; none of #887, #890, #892 or #897 touch that path.')
P('- Native Flash-Next verify attention is a sparse top-k kernel (`attn_rows_sparse`, 12 full-attention layers, 2048-key budget). It is 3.2% of a decode cycle at 32K and 3.0% at 128K (37-step GPU profile, M5 Pro), so a matrix-unit port could gain about 2% at best. Not built.')
P('- Old build `71826a86` against new `a2f42108`, native Flash-Next, interleaved A/B, n=3 at 32K and 128K and n=2 at 4K (one 4K run lost to a GPU out-of-memory error; see `bench/results/2026-11-03-m5-pro-flash-next-attn-ab/`): decode median 4K +3.1% (n=2, pairs +1.1 to +5.1%), 32K -5.8% (pairs -12.3 to -3.2%), 128K +7.0% (pairs +1.9 to +7.0%); prefill -2.0%, -1.5%, -5.2%. The sign changes with context length, the diff does not touch the native Flash-Next verify path, and the Mac sat on 5-10 GB of swap, so read it as run-to-run drift (about the same), not a speedup or a regression.')
P('- MLX cannot run Flash-Next on this Mac: the 4-bit pack is about 100 GB and the 2-bit about 81 GB against 48 GB of memory and 92 GiB of free disk.\n')
P('## What #892 changed, in plain words\n')
P('#892 moved the 35B-A3B (and Clover) draft-verify attention onto the M5 matrix units. It makes decoding at very long contexts faster on the Max (35B: 97 to 135 tokens per second at 249K tokens) and has no effect at 4K to 32K or on the poster row. It does not apply to Flash-Next: that model attends over at most 2,048 selected keys, so its attention was never the slow part.\n')
P('## Poster cross-check (README M5 Pro 48 GB rows against this re-measure)\n')
import subprocess
pj=json.load(open(os.path.join(HERE,'..','..','..','tools','readme_images','readme_images.json')))  # the README poster's source, in this checkout
rows={r['model']:r['cells'] for m in pj['poster']['macs'] if 'M5 Pro' in m['name'] for r in m['rows']}
P('| Model | Poster Kapitsa (decode / 4K prefill) | This run | Poster MLX cell | This run (same engine path) |'); P('|---|---|---|---|---|')
XC=[('Qwen3.8 27B','q38-27b','mlxvlm-mtp'),('Qwen3.6 35B-A3B','q36-35b','mlxvlm-dflash2'),('Lightning 30B','lightning','mlxlm')]
for mod,pre,me in XC:
    c=rows[mod]; k=c['Kapitsa']; ml=c['MLX']
    kl=legs(pre+'-kapitsa','harness-runs'); ll=legs('%s-%s'%(pre,me),'harness-runs')
    kd=short(kl,'dec0' if False else 'dec'); kp=short(kl,'pf4'); md=short(ll,'dec'); mp=short(ll,'pf4')
    P('| %s | %s / %s | %s / %s | %s %s (%s) | %s / %s |'%(mod,k['value'],k.get('prefill'),fmt(kd),fmt(kp),ml['value'],ml.get('method',''),ml.get('prefill'),fmt(md),fmt(mp)))
P('\nAgainst the poster, decode is within 6% in all six cells and prefill within 9% (the 9% is the contended 27B mlx-vlm 4K reading, 458 against 421) on current main (`287c0403`), for Kapitsa and for the MLX column. No poster cell changes: the poster\'s own standard is the median of three flag-free runs, and only one 27B Kapitsa leg is flag-free.\n')
P('## Limits\n')
P('- 128K legs (27B Kapitsa, 27B mlx-lm, Lightning): cannot measure tonight: foreign GPU load from open apps (about 15% in the sweep phase) and swap. Rerun with apps closed.')
bat=[x for x in AC if not x[1]]
bat=[x for x in AC if not x[1]]
P('- Power: the Mac was on battery earlier on 3 Nov until 18:18 local (battery fell to 2%%). The 30-second power log starts at 18:19, so no earlier leg is used in the tables. The Flash-Next old/new A/B and the decode profile ran earlier still, 12:17-13:31 local, mostly on battery; their speeds are drift only and are not counted. The Flash-Next bound uses only the 3.0-3.2%% attention share from the profile. Battery samples inside the log (local time): %s; a leg overlapping one is void.'%(', '.join(sorted({x[0].strftime('%H:%M') for x in bat})) or 'none'))
P('- No poster cell changes: the README M5 Pro cells reproduce (decode within 6%, prefill within 9%; see the cross-check), so no poster PR is needed.')
P('## Appendix: 32K and 127K prompts, indicative only (tokens per second)\n')
P('| Model | Engine | 32K decode | 127K decode | 127K prefill | legs |'); P('|---|---|---|---|---|---|')
for name,pre,engs,tag in M:
    for e,lab in (('kapitsa','kapitsa'),('mlxlm','mlxlm')):
        lg=legs('%s-%s-128k'%(tag,lab),'harness-runs-long')
        if not lg: P('| %s | %s | – | – | – | cannot measure tonight: foreign GPU load from open apps |'%(name,NAMES[e])); continue
        if not any(not any('finish_reason' in f for f in l['r'].get('flags',[])) and (l['ac'] or l['counts']) for l in lg): P('| %s | %s | – | – | – | cannot measure tonight: foreign GPU load from open apps (%d leg%s ended early or voided) |'%(name,NAMES[e],len(lg),'' if len(lg)==1 else 's')); continue
        d32=longpt(lg,32,'decode_tps'); d127=longpt(lg,127,'decode_tps'); p127=longpt(lg,127,'prefill_tps')
        f=lambda v: '–' if v[0] is None else '%s%s'%(v[0],'' if v[2]=='valid' else '*')
        P('| %s | %s | %s | %s | %s%s | %d (%d valid) |'%(name,NAMES[e],f(d32),f(d127),p127[0] if p127[0] else '–','' if p127[2]=='valid' else ' (contended)',len(lg),sum(l['counts'] for l in lg)))
P('\n\\* clean decode phase; prefill during the 127K sweep carried 7-17% foreign GPU load on every leg, so prefill ratios at 127K are indicative only.\n')
S=['**Summary (M5 Pro 48 GB, 3 Nov 2026): decode speed against the strongest MLX path for each model.**','']
S+=['- %s: Kapitsa is **%s** than %s (%s).'%(h[0],h[1].split(' (')[0],h[2],h[3]) for h in hl]
S+=['- Scope: "strongest MLX path" means mlx-lm or mlx-vlm. On the README poster, mlx-serve ties Kapitsa on the 27B (78 tok/s).']
S+=['- The README poster is unchanged: its M5 Pro cells reproduce (decode within 6%, prefill within 9%). 128K could not be measured tonight (apps open), and Flash-Next gains nothing from #892.','']
o[SUMSLOT:SUMSLOT]=S
print('\n'.join(o))
